//! A sorted list backed by a two-level list-of-lists layout.
//!
//! Values live in a `Vec` of sorted sublists, each holding at most `2 * load`
//! elements. Because every sublist is small, inserting or removing a value only
//! shifts a bounded number of elements instead of the whole sequence.
//!
//! A positional index tree (a flattened, implicit binary tree of subtree sizes)
//! sits on top of the sublists so that lookup by rank -- `get`, `pop`,
//! `index_of` -- stays logarithmic rather than scanning every sublist.

use std::cmp::Ordering;
use std::fmt;
use std::iter::FromIterator;
use std::ops::Index;

/// Default maximum sublist occupancy before a sublist is split in half.
pub const DEFAULT_LOAD_FACTOR: usize = 1000;

/// A sorted sequence that keeps duplicates.
pub struct SortedList<T> {
    /// Sorted sublists; concatenating them yields the whole sorted sequence.
    /// A sublist is never empty.
    lists: Vec<Vec<T>>,
    /// Flattened index tree of subtree sizes, or empty when not built.
    index: Vec<usize>,
    /// Offset of the leaf row (the per-sublist lengths) inside `index`.
    offset: usize,
    /// Total number of elements.
    len: usize,
    /// Target sublist occupancy.
    load: usize,
}

impl<T> SortedList<T> {
    /// Creates an empty list using [`DEFAULT_LOAD_FACTOR`].
    pub fn new() -> Self {
        Self::with_load_factor(DEFAULT_LOAD_FACTOR)
    }

    /// Creates an empty list whose sublists hold up to `2 * load` elements.
    ///
    /// # Panics
    ///
    /// Panics if `load` is zero.
    pub fn with_load_factor(load: usize) -> Self {
        assert!(load > 0, "load factor must be positive");
        SortedList {
            lists: Vec::new(),
            index: Vec::new(),
            offset: 0,
            len: 0,
            load,
        }
    }

    /// Number of elements in the list.
    pub fn len(&self) -> usize {
        self.len
    }

    /// Returns `true` when the list holds no elements.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// The configured load factor.
    pub fn load_factor(&self) -> usize {
        self.load
    }

    /// Removes every element, keeping the load factor.
    pub fn clear(&mut self) {
        self.lists.clear();
        self.index.clear();
        self.offset = 0;
        self.len = 0;
    }

    /// Iterates over the elements in ascending order.
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            inner: self.lists.iter().flatten(),
            remaining: self.len,
        }
    }

    /// Returns the element at rank `idx`, or `None` when out of bounds.
    pub fn get(&self, idx: usize) -> Option<&T> {
        let (pos, sub_idx) = self.locate_rank(idx)?;
        Some(&self.lists[pos][sub_idx])
    }

    /// Returns the smallest element.
    pub fn first(&self) -> Option<&T> {
        self.lists.first().and_then(|sub| sub.first())
    }

    /// Returns the largest element.
    pub fn last(&self) -> Option<&T> {
        self.lists.last().and_then(|sub| sub.last())
    }

    /// Removes and returns the element at rank `idx`.
    pub fn pop(&mut self, idx: usize) -> Option<T> {
        let (pos, sub_idx) = self.locate_rank(idx)?;
        Some(self.delete_at(pos, sub_idx))
    }

    /// Removes and returns the smallest element.
    pub fn pop_first(&mut self) -> Option<T> {
        if self.len == 0 {
            None
        } else {
            Some(self.delete_at(0, 0))
        }
    }

    /// Removes and returns the largest element.
    pub fn pop_last(&mut self) -> Option<T> {
        if self.len == 0 {
            return None;
        }
        let pos = self.lists.len() - 1;
        let sub_idx = self.lists[pos].len() - 1;
        Some(self.delete_at(pos, sub_idx))
    }

    /// Copies the elements into a `Vec` in ascending order.
    pub fn to_vec(&self) -> Vec<T>
    where
        T: Clone,
    {
        self.iter().cloned().collect()
    }

    /// Consumes the list, returning its elements in ascending order.
    pub fn into_vec(self) -> Vec<T> {
        let mut out = Vec::with_capacity(self.len);
        for sub in self.lists {
            out.extend(sub);
        }
        out
    }

    /// Rebuilds the positional index tree over the current sublists.
    ///
    /// The tree is stored as consecutive rows, deepest row last: the final row
    /// holds one entry per sublist and each row above holds the pairwise sums of
    /// the row below it.
    fn build_index(&mut self) {
        self.index.clear();
        self.offset = 0;
        if self.lists.is_empty() {
            return;
        }

        let row0: Vec<usize> = self.lists.iter().map(Vec::len).collect();
        if row0.len() == 1 {
            self.index = row0;
            return;
        }

        let mut row1: Vec<usize> = row0.chunks(2).map(|pair| pair.iter().sum()).collect();
        if row1.len() == 1 {
            self.index = row1;
            self.index.extend_from_slice(&row0);
            self.offset = 1;
            return;
        }

        // Pad the second row to a power of two so every row above it is even
        // sized and the tree stays perfectly shaped.
        let size = row1.len().next_power_of_two();
        row1.resize(size, 0);

        let mut rows: Vec<Vec<usize>> = vec![row0, row1];
        while rows.last().map_or(0, Vec::len) > 1 {
            let row: Vec<usize> = rows
                .last()
                .unwrap()
                .chunks(2)
                .map(|pair| pair.iter().sum())
                .collect();
            rows.push(row);
        }

        let total: usize = rows.iter().map(Vec::len).sum();
        let mut index = Vec::with_capacity(total);
        for row in rows.into_iter().rev() {
            index.extend(row);
        }
        self.index = index;
        self.offset = size * 2 - 1;
    }

    /// Ensures the index tree is present whenever there is anything to index.
    fn ensure_index(&mut self) {
        if self.index.is_empty() && !self.lists.is_empty() {
            self.build_index();
        }
    }

    /// Translates a global rank into `(sublist, offset within sublist)`.
    fn locate_rank(&self, rank: usize) -> Option<(usize, usize)> {
        if rank >= self.len {
            return None;
        }
        let mut idx = rank;
        if idx < self.lists[0].len() {
            return Some((0, idx));
        }
        if self.index.is_empty() {
            // No index available: walk the sublists directly.
            let mut pos = 0;
            while idx >= self.lists[pos].len() {
                idx -= self.lists[pos].len();
                pos += 1;
            }
            return Some((pos, idx));
        }

        let mut pos = 0usize;
        let mut child = 1usize;
        while child < self.index.len() {
            let size = self.index[child];
            if idx < size {
                pos = child;
            } else {
                idx -= size;
                pos = child + 1;
            }
            child = (pos << 1) + 1;
        }
        Some((pos - self.offset, idx))
    }

    /// Translates `(sublist, offset within sublist)` into a global rank.
    fn rank_of(&self, pos: usize, sub_idx: usize) -> usize {
        if pos == 0 {
            return sub_idx;
        }
        if self.index.is_empty() {
            let before: usize = self.lists[..pos].iter().map(Vec::len).sum();
            return before + sub_idx;
        }
        // Sum the left siblings encountered while walking up to the root.
        let mut total = 0usize;
        let mut node = pos + self.offset;
        while node > 0 {
            if node & 1 == 0 {
                total += self.index[node - 1];
            }
            node = (node - 1) >> 1;
        }
        total + sub_idx
    }

    /// Records one extra element in `lists[pos]`, splitting it when overfull.
    fn expand(&mut self, pos: usize) {
        if self.lists[pos].len() > (self.load << 1) {
            let half = self.lists[pos].split_off(self.load);
            self.lists.insert(pos + 1, half);
            self.index.clear();
            self.offset = 0;
        } else if !self.index.is_empty() {
            let mut node = self.offset + pos;
            while node > 0 {
                self.index[node] += 1;
                node = (node - 1) >> 1;
            }
            self.index[0] += 1;
        }
    }

    /// Removes `lists[pos][sub_idx]`, merging or dropping sublists as needed.
    fn delete_at(&mut self, pos: usize, sub_idx: usize) -> T {
        let value = self.lists[pos].remove(sub_idx);
        self.len -= 1;
        let sub_len = self.lists[pos].len();

        if sub_len > (self.load >> 1) || self.lists.len() == 1 {
            if sub_len == 0 {
                // Only possible with a single, now-empty sublist.
                self.lists.remove(pos);
                self.index.clear();
                self.offset = 0;
            } else if !self.index.is_empty() {
                let mut node = self.offset + pos;
                while node > 0 {
                    self.index[node] -= 1;
                    node = (node - 1) >> 1;
                }
                self.index[0] -= 1;
            }
        } else {
            // Sublist ran too thin: fold it into its left neighbour, then let
            // `expand` split the result back apart if it grew too large.
            let pos = if pos == 0 { 1 } else { pos };
            let prev = pos - 1;
            let moved = self.lists.remove(pos);
            self.lists[prev].extend(moved);
            self.index.clear();
            self.offset = 0;
            self.expand(prev);
        }

        self.ensure_index();
        value
    }

    /// Binary searches the sublist maxima; `go_right` reports "look further right".
    fn maxes_partition_point<F>(&self, mut go_right: F) -> usize
    where
        F: FnMut(&T) -> bool,
    {
        let mut lo = 0usize;
        let mut hi = self.lists.len();
        while lo < hi {
            let mid = lo + (hi - lo) / 2;
            let max = self.lists[mid]
                .last()
                .expect("sublists are never left empty");
            if go_right(max) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    /// Finds the first element for which `cmp` is not `Less`, as `(sublist, offset)`.
    ///
    /// `cmp` compares a stored element against the sought key.
    fn seek_by<F>(&self, cmp: &mut F) -> (usize, usize)
    where
        F: FnMut(&T) -> Ordering,
    {
        if self.lists.is_empty() {
            return (0, 0);
        }
        let pos = self.maxes_partition_point(|max| cmp(max) == Ordering::Less);
        if pos == self.lists.len() {
            return (pos, 0);
        }
        let sub_idx = self.lists[pos].partition_point(|item| cmp(item) == Ordering::Less);
        (pos, sub_idx)
    }

    /// Position of an element comparing `Equal` under `cmp`, if present.
    fn locate_by<F>(&self, mut cmp: F) -> Option<(usize, usize)>
    where
        F: FnMut(&T) -> Ordering,
    {
        let (pos, sub_idx) = self.seek_by(&mut cmp);
        let sub = self.lists.get(pos)?;
        match sub.get(sub_idx) {
            Some(item) if cmp(item) == Ordering::Equal => Some((pos, sub_idx)),
            _ => None,
        }
    }

    /// Returns a reference to an element comparing `Equal` under `cmp`.
    pub fn find_by<F>(&self, cmp: F) -> Option<&T>
    where
        F: FnMut(&T) -> Ordering,
    {
        let (pos, sub_idx) = self.locate_by(cmp)?;
        Some(&self.lists[pos][sub_idx])
    }

    /// Returns a mutable reference to an element comparing `Equal` under `cmp`.
    ///
    /// The caller must not mutate the element in a way that changes its order.
    pub fn find_mut_by<F>(&mut self, cmp: F) -> Option<&mut T>
    where
        F: FnMut(&T) -> Ordering,
    {
        let (pos, sub_idx) = self.locate_by(cmp)?;
        Some(&mut self.lists[pos][sub_idx])
    }

    /// Removes and returns an element comparing `Equal` under `cmp`.
    pub fn remove_by<F>(&mut self, cmp: F) -> Option<T>
    where
        F: FnMut(&T) -> Ordering,
    {
        let (pos, sub_idx) = self.locate_by(cmp)?;
        Some(self.delete_at(pos, sub_idx))
    }

    /// Rank of the first element comparing `Equal` or `Greater` under `cmp`.
    pub fn bisect_left_by<F>(&self, mut cmp: F) -> usize
    where
        F: FnMut(&T) -> Ordering,
    {
        let (pos, sub_idx) = self.seek_by(&mut cmp);
        if pos == self.lists.len() {
            self.len
        } else {
            self.rank_of(pos, sub_idx)
        }
    }

    /// Rank of the first element comparing `Greater` under `cmp`.
    pub fn bisect_right_by<F>(&self, mut cmp: F) -> usize
    where
        F: FnMut(&T) -> Ordering,
    {
        // Treat `Equal` as "keep going right" to land past the run of equals.
        let mut shifted = |item: &T| match cmp(item) {
            Ordering::Greater => Ordering::Greater,
            _ => Ordering::Less,
        };
        let (pos, sub_idx) = self.seek_by(&mut shifted);
        if pos == self.lists.len() {
            self.len
        } else {
            self.rank_of(pos, sub_idx)
        }
    }

    /// Replaces the sublists with `values`, which must already be sorted.
    pub(crate) fn rebuild_from_sorted(&mut self, values: Vec<T>) {
        self.clear();
        let load = self.load;
        let mut lists: Vec<Vec<T>> = Vec::with_capacity(values.len() / load + 1);
        let mut current: Vec<T> = Vec::with_capacity(load.min(values.len()));
        let mut len = 0usize;
        for value in values {
            current.push(value);
            len += 1;
            if current.len() == load {
                lists.push(std::mem::replace(&mut current, Vec::with_capacity(load)));
            }
        }
        if !current.is_empty() {
            lists.push(current);
        }
        self.lists = lists;
        self.len = len;
        self.build_index();
    }
}

impl<T: Ord> SortedList<T> {
    /// Inserts `value`, keeping any existing equal elements.
    pub fn insert(&mut self, value: T) {
        if self.lists.is_empty() {
            self.lists.push(vec![value]);
            self.len = 1;
            self.build_index();
            return;
        }
        // `bisect_right` semantics: land after equal elements.
        let pos = self.maxes_partition_point(|max| *max <= value);
        if pos == self.lists.len() {
            let pos = self.lists.len() - 1;
            self.lists[pos].push(value);
            self.len += 1;
            self.expand(pos);
        } else {
            let sub_idx = self.lists[pos].partition_point(|item| *item <= value);
            self.lists[pos].insert(sub_idx, value);
            self.len += 1;
            self.expand(pos);
        }
        self.ensure_index();
    }

    /// Inserts `value` only when no equal element is present.
    ///
    /// Returns `true` when the value was inserted.
    pub fn insert_if_absent(&mut self, value: T) -> bool {
        if self.lists.is_empty() {
            self.insert(value);
            return true;
        }
        let pos = self.maxes_partition_point(|max| *max < value);
        if pos == self.lists.len() {
            let pos = self.lists.len() - 1;
            self.lists[pos].push(value);
            self.len += 1;
            self.expand(pos);
        } else {
            let sub_idx = self.lists[pos].partition_point(|item| *item < value);
            if self.lists[pos]
                .get(sub_idx)
                .map_or(false, |item| *item == value)
            {
                return false;
            }
            self.lists[pos].insert(sub_idx, value);
            self.len += 1;
            self.expand(pos);
        }
        self.ensure_index();
        true
    }

    /// Inserts `value`, replacing and returning an existing equal element.
    pub fn insert_or_replace(&mut self, value: T) -> Option<T> {
        if self.lists.is_empty() {
            self.insert(value);
            return None;
        }
        let pos = self.maxes_partition_point(|max| *max < value);
        if pos == self.lists.len() {
            let pos = self.lists.len() - 1;
            self.lists[pos].push(value);
            self.len += 1;
            self.expand(pos);
        } else {
            let sub_idx = self.lists[pos].partition_point(|item| *item < value);
            if self.lists[pos]
                .get(sub_idx)
                .map_or(false, |item| *item == value)
            {
                return Some(std::mem::replace(&mut self.lists[pos][sub_idx], value));
            }
            self.lists[pos].insert(sub_idx, value);
            self.len += 1;
            self.expand(pos);
        }
        self.ensure_index();
        None
    }

    /// Returns `true` when an element equal to `value` is present.
    pub fn contains(&self, value: &T) -> bool {
        self.locate_by(|item| item.cmp(value)).is_some()
    }

    /// Removes one element equal to `value`, reporting whether it was found.
    pub fn remove(&mut self, value: &T) -> bool {
        self.remove_by(|item| item.cmp(value)).is_some()
    }

    /// Rank of the first element not less than `value`.
    pub fn bisect_left(&self, value: &T) -> usize {
        self.bisect_left_by(|item| item.cmp(value))
    }

    /// Rank of the first element greater than `value`.
    pub fn bisect_right(&self, value: &T) -> usize {
        self.bisect_right_by(|item| item.cmp(value))
    }

    /// Rank of the first element equal to `value`, if present.
    pub fn index_of(&self, value: &T) -> Option<usize> {
        let (pos, sub_idx) = self.locate_by(|item| item.cmp(value))?;
        Some(self.rank_of(pos, sub_idx))
    }

    /// Number of elements equal to `value`.
    pub fn count(&self, value: &T) -> usize {
        self.bisect_right(value) - self.bisect_left(value)
    }

    /// Inserts every item, choosing between bulk rebuild and repeated inserts.
    pub fn extend_from<I: IntoIterator<Item = T>>(&mut self, items: I) {
        let mut values: Vec<T> = items.into_iter().collect();
        if values.is_empty() {
            return;
        }
        values.sort();
        if !self.lists.is_empty() {
            if values.len() * 4 < self.len {
                // Small addition relative to the list: point inserts win.
                for value in values {
                    self.insert(value);
                }
                return;
            }
            let existing = std::mem::take(&mut self.lists);
            let mut merged = Vec::with_capacity(self.len + values.len());
            for sub in existing {
                merged.extend(sub);
            }
            merged.extend(values);
            merged.sort();
            values = merged;
        }
        self.rebuild_from_sorted(values);
    }
}

/// Borrowing iterator over a [`SortedList`] in ascending order.
pub struct Iter<'a, T> {
    inner: std::iter::Flatten<std::slice::Iter<'a, Vec<T>>>,
    remaining: usize,
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<Self::Item> {
        let item = self.inner.next();
        if item.is_some() {
            self.remaining -= 1;
        }
        item
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<'a, T> DoubleEndedIterator for Iter<'a, T> {
    fn next_back(&mut self) -> Option<Self::Item> {
        let item = self.inner.next_back();
        if item.is_some() {
            self.remaining -= 1;
        }
        item
    }
}

impl<'a, T> ExactSizeIterator for Iter<'a, T> {}

impl<'a, T> IntoIterator for &'a SortedList<T> {
    type Item = &'a T;
    type IntoIter = Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

impl<T> IntoIterator for SortedList<T> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T>;

    fn into_iter(self) -> Self::IntoIter {
        self.into_vec().into_iter()
    }
}

impl<T: Ord> FromIterator<T> for SortedList<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        let mut list = SortedList::new();
        list.extend_from(iter);
        list
    }
}

impl<T: Ord> Extend<T> for SortedList<T> {
    fn extend<I: IntoIterator<Item = T>>(&mut self, iter: I) {
        self.extend_from(iter);
    }
}

impl<T> Index<usize> for SortedList<T> {
    type Output = T;

    fn index(&self, idx: usize) -> &Self::Output {
        self.get(idx).expect("index out of bounds")
    }
}

impl<T> Default for SortedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T: Clone> Clone for SortedList<T> {
    fn clone(&self) -> Self {
        SortedList {
            lists: self.lists.clone(),
            index: self.index.clone(),
            offset: self.offset,
            len: self.len,
            load: self.load,
        }
    }
}

impl<T: fmt::Debug> fmt::Debug for SortedList<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_list().entries(self.iter()).finish()
    }
}

impl<T: PartialEq> PartialEq for SortedList<T> {
    fn eq(&self, other: &Self) -> bool {
        self.len == other.len && self.iter().zip(other.iter()).all(|(a, b)| a == b)
    }
}

impl<T: Eq> Eq for SortedList<T> {}

#[cfg(test)]
mod tests {
    use super::*;

    /// Checks every structural invariant against a straightforward model.
    fn assert_consistent<T: Ord + Clone + fmt::Debug>(list: &SortedList<T>, model: &[T]) {
        assert_eq!(list.len(), model.len(), "len mismatch");
        assert_eq!(list.to_vec(), model.to_vec(), "contents mismatch");

        for sub in &list.lists {
            assert!(!sub.is_empty(), "sublist must never be empty");
            assert!(
                sub.len() <= list.load * 2,
                "sublist exceeded 2 * load: {}",
                sub.len()
            );
        }

        // Positional access must agree with the model at every rank.
        for (rank, expected) in model.iter().enumerate() {
            assert_eq!(list.get(rank), Some(expected), "get({rank})");
        }
        assert_eq!(list.get(model.len()), None, "get past the end");

        // The index tree, when present, must describe the real sublist sizes.
        if !list.index.is_empty() {
            assert_eq!(list.index[0], list.len, "index root must equal len");
            for (pos, sub) in list.lists.iter().enumerate() {
                assert_eq!(
                    list.index[list.offset + pos],
                    sub.len(),
                    "leaf {pos} out of date"
                );
            }
        }
    }

    #[test]
    fn insert_keeps_sorted_order_with_duplicates() {
        let mut list = SortedList::with_load_factor(2);
        let mut model = Vec::new();
        for value in [5, 1, 9, 1, 7, 3, 3, 3, 0, 8, 2, 6, 4] {
            list.insert(value);
            model.push(value);
            model.sort();
            assert_consistent(&list, &model);
        }
        assert_eq!(list.count(&3), 3);
        assert_eq!(list.count(&42), 0);
    }

    #[test]
    fn bisect_and_index_agree_with_linear_search() {
        let mut list = SortedList::with_load_factor(3);
        let model: Vec<i32> = vec![0, 0, 1, 3, 3, 3, 4, 7, 7, 9, 11, 11, 15, 20, 21, 22];
        for value in &model {
            list.insert(*value);
        }
        assert_consistent(&list, &model);
        for probe in -2..25 {
            let left = model.partition_point(|x| *x < probe);
            let right = model.partition_point(|x| *x <= probe);
            assert_eq!(list.bisect_left(&probe), left, "bisect_left({probe})");
            assert_eq!(list.bisect_right(&probe), right, "bisect_right({probe})");
            assert_eq!(list.contains(&probe), left != right, "contains({probe})");
            let expected = if left == right { None } else { Some(left) };
            assert_eq!(list.index_of(&probe), expected, "index_of({probe})");
        }
    }

    #[test]
    fn remove_merges_and_drops_sublists() {
        let mut list = SortedList::with_load_factor(2);
        let mut model: Vec<i32> = (0..40).collect();
        list.extend_from(model.clone());
        assert_consistent(&list, &model);

        // Remove from the middle, the front and the back in turn.
        for target in [20, 0, 39, 21, 1, 38, 19] {
            assert!(list.remove(&target));
            model.retain(|x| *x != target);
            assert_consistent(&list, &model);
        }
        assert!(!list.remove(&20), "already removed");

        while let Some(first) = list.first().copied() {
            assert!(list.remove(&first));
            model.retain(|x| *x != first);
            assert_consistent(&list, &model);
        }
        assert!(list.is_empty());
        assert_eq!(list.first(), None);
        assert_eq!(list.last(), None);
    }

    #[test]
    fn pop_walks_the_index_tree() {
        let mut list = SortedList::with_load_factor(2);
        let mut model: Vec<i32> = (0..60).rev().collect();
        for value in model.clone() {
            list.insert(value);
        }
        model.sort();
        assert_consistent(&list, &model);

        // Pop from a rotating set of ranks to exercise merges mid-tree.
        while !model.is_empty() {
            let rank = model.len() / 2;
            assert_eq!(list.pop(rank), Some(model.remove(rank)));
            assert_consistent(&list, &model);
        }
        assert_eq!(list.pop(0), None);
    }

    #[test]
    fn pop_first_and_last_track_the_ends() {
        let mut list: SortedList<i32> = (0..25).collect();
        assert_eq!(list.pop_first(), Some(0));
        assert_eq!(list.pop_last(), Some(24));
        assert_eq!(list.first(), Some(&1));
        assert_eq!(list.last(), Some(&23));
        assert_eq!(list.len(), 23);
    }

    /// Deterministic pseudo-random sequence: no external crates, no clock.
    fn lcg(state: &mut u64) -> u64 {
        *state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        *state >> 33
    }

    #[test]
    fn randomized_operations_match_a_vec_model() {
        for load in [1usize, 2, 3, 5, 8] {
            let mut state = 0x2545F4914F6CDD1Du64 ^ (load as u64);
            let mut list = SortedList::with_load_factor(load);
            let mut model: Vec<i64> = Vec::new();
            for step in 0..1200 {
                let value = (lcg(&mut state) % 60) as i64;
                if lcg(&mut state) % 3 == 0 && !model.is_empty() {
                    let rank = (lcg(&mut state) as usize) % model.len();
                    if lcg(&mut state) % 2 == 0 {
                        assert_eq!(list.pop(rank), Some(model.remove(rank)), "step {step}");
                    } else {
                        let present = model.contains(&value);
                        assert_eq!(list.remove(&value), present, "step {step}");
                        if present {
                            let at = model.iter().position(|x| *x == value).unwrap();
                            model.remove(at);
                        }
                    }
                } else {
                    list.insert(value);
                    let at = model.partition_point(|x| *x <= value);
                    model.insert(at, value);
                }
                assert_eq!(list.len(), model.len(), "step {step}");
                assert_eq!(list.get(0), model.first(), "step {step}");
            }
            assert_consistent(&list, &model);
        }
    }

    #[test]
    fn extend_uses_both_bulk_and_point_paths() {
        // Bulk path: the addition is large relative to the existing contents.
        let mut bulk = SortedList::with_load_factor(4);
        bulk.insert(100);
        bulk.extend_from(0..30);
        let mut expected: Vec<i32> = (0..30).collect();
        expected.push(100);
        assert_consistent(&bulk, &expected);

        // Point path: the addition is small relative to the existing contents.
        let mut point: SortedList<i32> = SortedList::with_load_factor(4);
        point.extend_from(0..100);
        point.extend_from([50, -1, 200]);
        let mut expected: Vec<i32> = (0..100).collect();
        expected.push(50);
        expected.push(-1);
        expected.push(200);
        expected.sort();
        assert_consistent(&point, &expected);

        // Extending with nothing must leave the list untouched.
        let before = point.to_vec();
        point.extend_from(Vec::<i32>::new());
        assert_eq!(point.to_vec(), before);
    }

    #[test]
    fn insert_if_absent_and_replace_respect_equality() {
        let mut list = SortedList::with_load_factor(2);
        for value in 0..20 {
            assert!(list.insert_if_absent(value));
        }
        for value in 0..20 {
            assert!(!list.insert_if_absent(value));
        }
        assert_eq!(list.len(), 20);
        assert!(list.insert_if_absent(100), "value above every maximum");
        assert_eq!(list.last(), Some(&100));

        assert_eq!(list.insert_or_replace(5), Some(5));
        assert_eq!(list.insert_or_replace(500), None);
        assert_eq!(list.last(), Some(&500));
    }

    #[test]
    fn large_input_stays_consistent() {
        let mut list: SortedList<i32> = SortedList::new();
        for value in (0..5000).rev() {
            list.insert(value);
        }
        assert_eq!(list.len(), 5000);
        for rank in [0usize, 1, 999, 1000, 1001, 2500, 4998, 4999] {
            assert_eq!(list.get(rank), Some(&(rank as i32)));
        }
        assert_eq!(list.get(5000), None);
        assert_eq!(list.index_of(&4321), Some(4321));
        assert!(list.iter().copied().eq(0..5000));
        assert!(list.iter().rev().copied().eq((0..5000).rev()));
        assert_eq!(list.iter().len(), 5000);
    }

    #[test]
    fn iteration_and_conversions_round_trip() {
        let list: SortedList<i32> = vec![3, 1, 2, 1].into_iter().collect();
        assert_eq!(list.to_vec(), vec![1, 1, 2, 3]);
        assert_eq!(format!("{:?}", list), "[1, 1, 2, 3]");
        assert_eq!(list[0], 1);
        assert_eq!(list[3], 3);
        assert_eq!(list.clone(), list);
        assert_eq!(list.into_vec(), vec![1, 1, 2, 3]);
    }

    #[test]
    fn clear_resets_every_field() {
        let mut list: SortedList<i32> = (0..50).collect();
        list.clear();
        assert!(list.is_empty());
        assert_eq!(list.len(), 0);
        assert_eq!(list.get(0), None);
        assert_eq!(list.to_vec(), Vec::<i32>::new());
        assert!(!list.contains(&1));
        assert_eq!(list.bisect_left(&1), 0);
        assert_eq!(list.bisect_right(&1), 0);
        assert_eq!(list.index_of(&1), None);
        list.insert(7);
        assert_eq!(list.to_vec(), vec![7]);
    }

    #[test]
    #[should_panic(expected = "load factor must be positive")]
    fn zero_load_factor_is_rejected() {
        let _: SortedList<i32> = SortedList::with_load_factor(0);
    }
}

