//! A sorted set of unique values, layered on [`SortedList`].
//!
//! Membership tests and insertions are binary searches over the same two-level
//! layout the list uses, so no hashing -- and therefore no `Hash` bound -- is
//! required: `Ord` alone is enough.

use std::cmp::Ordering;
use std::fmt;

use crate::sorted_list::{SortedList, DEFAULT_LOAD_FACTOR};

/// A sorted collection holding at most one copy of each value.
pub struct SortedSet<T> {
    list: SortedList<T>,
}

impl<T> SortedSet<T> {
    /// Creates an empty set using [`DEFAULT_LOAD_FACTOR`].
    pub fn new() -> Self {
        Self::with_load_factor(DEFAULT_LOAD_FACTOR)
    }

    /// Creates an empty set with an explicit load factor.
    pub fn with_load_factor(load: usize) -> Self {
        SortedSet {
            list: SortedList::with_load_factor(load),
        }
    }

    /// Number of values in the set.
    pub fn len(&self) -> usize {
        self.list.len()
    }

    /// Returns `true` when the set holds no values.
    pub fn is_empty(&self) -> bool {
        self.list.is_empty()
    }

    /// The configured load factor.
    pub fn load_factor(&self) -> usize {
        self.list.load_factor()
    }

    /// Removes every value.
    pub fn clear(&mut self) {
        self.list.clear();
    }

    /// Iterates over the values in ascending order.
    pub fn iter(&self) -> crate::sorted_list::Iter<'_, T> {
        self.list.iter()
    }

    /// Returns the value at rank `idx`.
    pub fn get(&self, idx: usize) -> Option<&T> {
        self.list.get(idx)
    }

    /// Returns the smallest value.
    pub fn first(&self) -> Option<&T> {
        self.list.first()
    }

    /// Returns the largest value.
    pub fn last(&self) -> Option<&T> {
        self.list.last()
    }

    /// Removes and returns the smallest value.
    pub fn pop_first(&mut self) -> Option<T> {
        self.list.pop_first()
    }

    /// Removes and returns the largest value.
    pub fn pop_last(&mut self) -> Option<T> {
        self.list.pop_last()
    }

    /// Removes and returns the value at rank `idx`.
    pub fn pop(&mut self, idx: usize) -> Option<T> {
        self.list.pop(idx)
    }

    /// Copies the values into a `Vec` in ascending order.
    pub fn to_vec(&self) -> Vec<T>
    where
        T: Clone,
    {
        self.list.to_vec()
    }

    /// Consumes the set, returning its values in ascending order.
    pub fn into_vec(self) -> Vec<T> {
        self.list.into_vec()
    }

    /// Borrows the backing list.
    pub fn as_sorted_list(&self) -> &SortedList<T> {
        &self.list
    }

    /// Builds a set directly from strictly increasing, de-duplicated values.
    fn from_sorted_unique(values: Vec<T>, load: usize) -> Self {
        let mut list = SortedList::with_load_factor(load);
        list.rebuild_from_sorted(values);
        SortedSet { list }
    }
}

impl<T: Ord> SortedSet<T> {
    /// Inserts `value`, reporting `true` when it was not already present.
    pub fn insert(&mut self, value: T) -> bool {
        self.list.insert_if_absent(value)
    }

    /// Inserts `value`, returning the value it displaced when already present.
    pub fn replace(&mut self, value: T) -> Option<T> {
        self.list.insert_or_replace(value)
    }

    /// Returns `true` when `value` is a member of the set.
    pub fn contains(&self, value: &T) -> bool {
        self.list.contains(value)
    }

    /// Removes `value`, reporting whether it was present.
    pub fn remove(&mut self, value: &T) -> bool {
        self.list.remove(value)
    }

    /// Rank of `value`, if present.
    pub fn index_of(&self, value: &T) -> Option<usize> {
        self.list.index_of(value)
    }

    /// Rank of the first value not less than `value`.
    pub fn bisect_left(&self, value: &T) -> usize {
        self.list.bisect_left(value)
    }

    /// Rank of the first value greater than `value`.
    pub fn bisect_right(&self, value: &T) -> usize {
        self.list.bisect_right(value)
    }

    /// Inserts every item from `items`.
    pub fn extend_from<I: IntoIterator<Item = T>>(&mut self, items: I) {
        for value in items {
            self.insert(value);
        }
    }

    /// Values present in `self` or `other`.
    pub fn union_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len() + other.len());
        self.merge_walk(other, |ordering| ordering != Ordering::Greater, true, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Values present in both `self` and `other`.
    pub fn intersection_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len().min(other.len()));
        self.merge_walk(other, |ordering| ordering == Ordering::Equal, false, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Values present in `self` but not in `other`.
    pub fn difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len());
        self.merge_walk(other, |ordering| ordering == Ordering::Less, false, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Values present in exactly one of `self` and `other`.
    pub fn symmetric_difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len() + other.len());
        self.merge_walk(other, |ordering| ordering != Ordering::Equal, true, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Walks both sorted sequences once, collecting the values that qualify.
    ///
    /// `keep` is asked about each value from `self` using how it compares to the
    /// current value from `other` (`Less` means "only in `self`", `Equal` means
    /// "in both"). `keep_other_only` decides whether values found solely in
    /// `other` are collected.
    fn merge_walk<F>(
        &self,
        other: &SortedSet<T>,
        keep: F,
        keep_other_only: bool,
        out: &mut Vec<T>,
    ) where
        T: Clone,
        F: Fn(Ordering) -> bool,
    {
        let mut left = self.iter().peekable();
        let mut right = other.iter().peekable();
        loop {
            match (left.peek(), right.peek()) {
                (Some(a), Some(b)) => match a.cmp(b) {
                    Ordering::Less => {
                        let a = left.next().expect("peeked");
                        if keep(Ordering::Less) {
                            out.push(a.clone());
                        }
                    }
                    Ordering::Greater => {
                        let b = right.next().expect("peeked");
                        if keep_other_only {
                            out.push(b.clone());
                        }
                    }
                    Ordering::Equal => {
                        let a = left.next().expect("peeked");
                        right.next();
                        if keep(Ordering::Equal) {
                            out.push(a.clone());
                        }
                    }
                },
                (Some(_), None) => {
                    let a = left.next().expect("peeked");
                    if keep(Ordering::Less) {
                        out.push(a.clone());
                    }
                }
                (None, Some(_)) => {
                    let b = right.next().expect("peeked");
                    if keep_other_only {
                        out.push(b.clone());
                    }
                }
                (None, None) => return,
            }
        }
    }

    /// Returns `true` when every value of `self` is also in `other`.
    pub fn is_subset_of(&self, other: &SortedSet<T>) -> bool {
        if self.len() > other.len() {
            return false;
        }
        let mut right = other.iter().peekable();
        for value in self.iter() {
            loop {
                match right.next() {
                    Some(candidate) => match candidate.cmp(value) {
                        Ordering::Less => continue,
                        Ordering::Equal => break,
                        Ordering::Greater => return false,
                    },
                    None => return false,
                }
            }
        }
        true
    }

    /// Returns `true` when every value of `other` is also in `self`.
    pub fn is_superset_of(&self, other: &SortedSet<T>) -> bool {
        other.is_subset_of(self)
    }

    /// Returns `true` when the two sets share no values.
    pub fn is_disjoint_from(&self, other: &SortedSet<T>) -> bool {
        let mut left = self.iter().peekable();
        let mut right = other.iter().peekable();
        while let (Some(a), Some(b)) = (left.peek(), right.peek()) {
            match a.cmp(b) {
                Ordering::Less => {
                    left.next();
                }
                Ordering::Greater => {
                    right.next();
                }
                Ordering::Equal => return false,
            }
        }
        true
    }
}

impl<'a, T> IntoIterator for &'a SortedSet<T> {
    type Item = &'a T;
    type IntoIter = crate::sorted_list::Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

impl<T> IntoIterator for SortedSet<T> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T>;

    fn into_iter(self) -> Self::IntoIter {
        self.into_vec().into_iter()
    }
}

impl<T: Ord> FromIterator<T> for SortedSet<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        let mut set = SortedSet::new();
        set.extend_from(iter);
        set
    }
}

impl<T: Ord> Extend<T> for SortedSet<T> {
    fn extend<I: IntoIterator<Item = T>>(&mut self, iter: I) {
        self.extend_from(iter);
    }
}

impl<T> Default for SortedSet<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T: Clone> Clone for SortedSet<T> {
    fn clone(&self) -> Self {
        SortedSet {
            list: self.list.clone(),
        }
    }
}

impl<T: fmt::Debug> fmt::Debug for SortedSet<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_set().entries(self.iter()).finish()
    }
}

impl<T: PartialEq> PartialEq for SortedSet<T> {
    fn eq(&self, other: &Self) -> bool {
        self.list == other.list
    }
}

impl<T: Eq> Eq for SortedSet<T> {}

#[cfg(test)]
mod tests {
    use super::*;

    fn set_of(values: &[i32]) -> SortedSet<i32> {
        let mut set = SortedSet::with_load_factor(2);
        for value in values {
            set.insert(*value);
        }
        set
    }

    #[test]
    fn insert_reports_novelty_and_deduplicates() {
        let mut set = SortedSet::with_load_factor(2);
        for value in [5, 1, 5, 3, 1, 9, 3] {
            set.insert(value);
        }
        assert_eq!(set.to_vec(), vec![1, 3, 5, 9]);
        assert!(set.insert(7));
        assert!(!set.insert(7));
        assert_eq!(set.len(), 5);
        assert_eq!(set.to_vec(), vec![1, 3, 5, 7, 9]);
    }

    #[test]
    fn membership_and_removal() {
        let mut set = set_of(&(0..40).collect::<Vec<i32>>());
        for value in 0..40 {
            assert!(set.contains(&value), "contains({value})");
        }
        assert!(!set.contains(&-1));
        assert!(!set.contains(&40));

        assert!(set.remove(&0));
        assert!(!set.remove(&0));
        assert!(set.remove(&39));
        assert!(set.remove(&20));
        assert_eq!(set.len(), 37);
        assert_eq!(set.first(), Some(&1));
        assert_eq!(set.last(), Some(&38));
        assert!(!set.contains(&20));
    }

    #[test]
    fn ranks_and_ends() {
        let set = set_of(&[10, 20, 30, 40, 50]);
        assert_eq!(set.get(0), Some(&10));
        assert_eq!(set.get(4), Some(&50));
        assert_eq!(set.get(5), None);
        assert_eq!(set.index_of(&30), Some(2));
        assert_eq!(set.index_of(&31), None);
        assert_eq!(set.bisect_left(&30), 2);
        assert_eq!(set.bisect_right(&30), 3);
        assert_eq!(set.bisect_left(&31), 3);
        assert_eq!(set.bisect_right(&99), 5);

        let mut set = set;
        assert_eq!(set.pop_first(), Some(10));
        assert_eq!(set.pop_last(), Some(50));
        assert_eq!(set.pop(1), Some(30));
        assert_eq!(set.to_vec(), vec![20, 40]);
    }

    #[test]
    fn union_matches_the_test6_scenario() {
        // Mirrors tests/test6: {0..n-1} unioned with {0, 2, ..., 2n-2}.
        for n in 0..40i32 {
            let mut s1 = SortedSet::new();
            let mut s2 = SortedSet::new();
            for i in 0..n {
                s1.insert(i);
                s2.insert(i * 2);
            }
            let s3 = s1.union_with(&s2);

            let mut expected: Vec<i32> = (0..n).collect();
            for i in 0..n {
                if !expected.contains(&(i * 2)) {
                    expected.push(i * 2);
                }
            }
            expected.sort();
            assert_eq!(s3.to_vec(), expected, "n = {n}");
            assert_eq!(s1.len(), n as usize);
            assert_eq!(s2.len(), n as usize);
            for i in 0..n {
                assert!(s3.contains(&i), "n = {n}, contains({i})");
            }
        }
    }

    #[test]
    fn union_is_symmetric_and_absorbs_duplicates() {
        let a = set_of(&[1, 3, 5, 7]);
        let b = set_of(&[3, 4, 5, 6]);
        let expected = vec![1, 3, 4, 5, 6, 7];
        assert_eq!(a.union_with(&b).to_vec(), expected);
        assert_eq!(b.union_with(&a).to_vec(), expected);

        let empty = SortedSet::<i32>::new();
        assert_eq!(a.union_with(&empty).to_vec(), a.to_vec());
        assert_eq!(empty.union_with(&a).to_vec(), a.to_vec());
        assert_eq!(empty.union_with(&empty).to_vec(), Vec::<i32>::new());
        assert!(empty.union_with(&empty).is_empty());
    }

    #[test]
    fn intersection_difference_and_symmetric_difference() {
        let a = set_of(&[1, 2, 3, 4, 5]);
        let b = set_of(&[4, 5, 6, 7]);
        assert_eq!(a.intersection_with(&b).to_vec(), vec![4, 5]);
        assert_eq!(b.intersection_with(&a).to_vec(), vec![4, 5]);
        assert_eq!(a.difference_with(&b).to_vec(), vec![1, 2, 3]);
        assert_eq!(b.difference_with(&a).to_vec(), vec![6, 7]);
        assert_eq!(
            a.symmetric_difference_with(&b).to_vec(),
            vec![1, 2, 3, 6, 7]
        );
        assert_eq!(
            b.symmetric_difference_with(&a).to_vec(),
            vec![1, 2, 3, 6, 7]
        );

        let empty = SortedSet::<i32>::new();
        assert!(a.intersection_with(&empty).is_empty());
        assert_eq!(a.difference_with(&empty).to_vec(), a.to_vec());
        assert_eq!(a.symmetric_difference_with(&empty).to_vec(), a.to_vec());
    }

    #[test]
    fn subset_superset_and_disjoint() {
        let a = set_of(&[1, 2, 3]);
        let b = set_of(&[1, 2, 3, 4, 5]);
        let c = set_of(&[9, 10]);
        let empty = SortedSet::<i32>::new();

        assert!(a.is_subset_of(&b));
        assert!(!b.is_subset_of(&a));
        assert!(b.is_superset_of(&a));
        assert!(a.is_subset_of(&a));
        assert!(empty.is_subset_of(&a));
        assert!(!a.is_subset_of(&empty));

        assert!(a.is_disjoint_from(&c));
        assert!(c.is_disjoint_from(&a));
        assert!(!a.is_disjoint_from(&b));
        assert!(empty.is_disjoint_from(&a));

        // A same-size, non-matching set must not read as a subset.
        assert!(!set_of(&[1, 2, 4]).is_subset_of(&a));
        // A value below every member of the other set must fail fast.
        assert!(!set_of(&[0]).is_subset_of(&a));
        // A value above every member must fail too.
        assert!(!set_of(&[4]).is_subset_of(&a));
    }

    #[test]
    fn set_algebra_matches_a_brute_force_model() {
        // Exhaustive over all subsets of 0..6 -- every overlap pattern.
        for left_bits in 0u32..64 {
            for right_bits in 0u32..64 {
                let left: Vec<i32> = (0..6).filter(|i| left_bits >> i & 1 == 1).collect();
                let right: Vec<i32> = (0..6).filter(|i| right_bits >> i & 1 == 1).collect();
                let a = set_of(&left);
                let b = set_of(&right);

                let union: Vec<i32> = (0..6)
                    .filter(|i| (left_bits | right_bits) >> i & 1 == 1)
                    .collect();
                let inter: Vec<i32> = (0..6)
                    .filter(|i| (left_bits & right_bits) >> i & 1 == 1)
                    .collect();
                let diff: Vec<i32> = (0..6)
                    .filter(|i| (left_bits & !right_bits) >> i & 1 == 1)
                    .collect();
                let sym: Vec<i32> = (0..6)
                    .filter(|i| (left_bits ^ right_bits) >> i & 1 == 1)
                    .collect();

                assert_eq!(a.union_with(&b).to_vec(), union, "{left_bits}|{right_bits}");
                assert_eq!(
                    a.intersection_with(&b).to_vec(),
                    inter,
                    "{left_bits}&{right_bits}"
                );
                assert_eq!(
                    a.difference_with(&b).to_vec(),
                    diff,
                    "{left_bits}-{right_bits}"
                );
                assert_eq!(
                    a.symmetric_difference_with(&b).to_vec(),
                    sym,
                    "{left_bits}^{right_bits}"
                );
                assert_eq!(
                    a.is_subset_of(&b),
                    left_bits & !right_bits == 0,
                    "subset {left_bits}/{right_bits}"
                );
                assert_eq!(
                    a.is_disjoint_from(&b),
                    left_bits & right_bits == 0,
                    "disjoint {left_bits}/{right_bits}"
                );
            }
        }
    }

    #[test]
    fn union_of_large_sets_stays_correct() {
        let mut s1 = SortedSet::new();
        let mut s2 = SortedSet::new();
        for i in 0..5000i32 {
            s1.insert(i);
            s2.insert(i * 2);
        }
        let s3 = s1.union_with(&s2);
        assert_eq!(s1.len(), 5000);
        assert_eq!(s2.len(), 5000);
        assert_eq!(s3.len(), 7500);
        assert!(s3.contains(&0));
        assert!(s3.contains(&4999));
        assert!(s3.contains(&9998));
        assert!(!s3.contains(&5001));
        assert!(!s3.contains(&9999));
        assert!(s3.iter().zip(s3.iter().skip(1)).all(|(a, b)| a < b));
    }

    #[test]
    fn replace_swaps_the_stored_value() {
        let mut set = set_of(&[1, 2, 3]);
        assert_eq!(set.replace(2), Some(2));
        assert_eq!(set.replace(4), None);
        assert_eq!(set.to_vec(), vec![1, 2, 3, 4]);
    }

    #[test]
    fn conversions_and_traits() {
        let set: SortedSet<i32> = vec![3, 1, 2, 1].into_iter().collect();
        assert_eq!(set.to_vec(), vec![1, 2, 3]);
        assert_eq!(format!("{:?}", set), "{1, 2, 3}");
        assert_eq!(set.clone(), set);
        assert_eq!(set.as_sorted_list().len(), 3);
        assert_eq!(set.iter().copied().collect::<Vec<i32>>(), vec![1, 2, 3]);
        assert_eq!(set.into_vec(), vec![1, 2, 3]);

        let mut set = SortedSet::<i32>::default();
        set.extend([5, 4, 5]);
        assert_eq!(set.to_vec(), vec![4, 5]);
        assert_eq!(set.load_factor(), DEFAULT_LOAD_FACTOR);
        set.clear();
        assert!(set.is_empty());
    }
}

