//! A sorted set of unique values, layered on [`SortedList`].
//!
//! Membership tests and insertions are binary searches over the same two-level
//! layout the list uses, so no hashing -- and therefore no `Hash` bound -- is
//! required: `Ord` alone is enough.

use std::cmp::Ordering;
use std::fmt;

use crate::sorted_list::{SortedList, DEFAULT_LOAD_FACTOR};

/// A sorted collection holding at most one copy of each value.
pub struct SortedSet<T> {
    list: SortedList<T>,
}

impl<T> SortedSet<T> {
    /// Creates an empty set using [`DEFAULT_LOAD_FACTOR`].
    pub fn new() -> Self {
        Self::with_load_factor(DEFAULT_LOAD_FACTOR)
    }

    /// Creates an empty set with an explicit load factor.
    pub fn with_load_factor(load: usize) -> Self {
        SortedSet {
            list: SortedList::with_load_factor(load),
        }
    }

    /// Number of values in the set.
    pub fn len(&self) -> usize {
        self.list.len()
    }

    /// Returns `true` when the set holds no values.
    pub fn is_empty(&self) -> bool {
        self.list.is_empty()
    }

    /// The configured load factor.
    pub fn load_factor(&self) -> usize {
        self.list.load_factor()
    }

    /// Removes every value.
    pub fn clear(&mut self) {
        self.list.clear();
    }

    /// Iterates over the values in ascending order.
    pub fn iter(&self) -> crate::sorted_list::Iter<'_, T> {
        self.list.iter()
    }

    /// Returns the value at rank `idx`.
    pub fn get(&self, idx: usize) -> Option<&T> {
        self.list.get(idx)
    }

    /// Returns the smallest value.
    pub fn first(&self) -> Option<&T> {
        self.list.first()
    }

    /// Returns the largest value.
    pub fn last(&self) -> Option<&T> {
        self.list.last()
    }

    /// Removes and returns the smallest value.
    pub fn pop_first(&mut self) -> Option<T> {
        self.list.pop_first()
    }

    /// Removes and returns the largest value.
    pub fn pop_last(&mut self) -> Option<T> {
        self.list.pop_last()
    }

    /// Removes and returns the value at rank `idx`.
    pub fn pop(&mut self, idx: usize) -> Option<T> {
        self.list.pop(idx)
    }

    /// Copies the values into a `Vec` in ascending order.
    pub fn to_vec(&self) -> Vec<T>
    where
        T: Clone,
    {
        self.list.to_vec()
    }

    /// Consumes the set, returning its values in ascending order.
    pub fn into_vec(self) -> Vec<T> {
        self.list.into_vec()
    }

    /// Borrows the backing list.
    pub fn as_sorted_list(&self) -> &SortedList<T> {
        &self.list
    }

    /// Builds a set directly from strictly increasing, de-duplicated values.
    fn from_sorted_unique(values: Vec<T>, load: usize) -> Self {
        let mut list = SortedList::with_load_factor(load);
        list.rebuild_from_sorted(values);
        SortedSet { list }
    }
}

impl<T: Ord> SortedSet<T> {
    /// Inserts `value`, reporting `true` when it was not already present.
    pub fn insert(&mut self, value: T) -> bool {
        self.list.insert_if_absent(value)
    }

    /// Inserts `value`, returning the value it displaced when already present.
    pub fn replace(&mut self, value: T) -> Option<T> {
        self.list.insert_or_replace(value)
    }

    /// Returns `true` when `value` is a member of the set.
    pub fn contains(&self, value: &T) -> bool {
        self.list.contains(value)
    }

    /// Removes `value`, reporting whether it was present.
    pub fn remove(&mut self, value: &T) -> bool {
        self.list.remove(value)
    }

    /// Rank of `value`, if present.
    pub fn index_of(&self, value: &T) -> Option<usize> {
        self.list.index_of(value)
    }

    /// Rank of the first value not less than `value`.
    pub fn bisect_left(&self, value: &T) -> usize {
        self.list.bisect_left(value)
    }

    /// Rank of the first value greater than `value`.
    pub fn bisect_right(&self, value: &T) -> usize {
        self.list.bisect_right(value)
    }

    /// Inserts every item from `items`.
    pub fn extend_from<I: IntoIterator<Item = T>>(&mut self, items: I) {
        for value in items {
            self.insert(value);
        }
    }

    /// Values present in `self` or `other`.
    pub fn union_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len() + other.len());
        self.merge_walk(other, |ordering| ordering != Ordering::Greater, true, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Values present in both `self` and `other`.
    pub fn intersection_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len().min(other.len()));
        self.merge_walk(other, |ordering| ordering == Ordering::Equal, false, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Values present in `self` but not in `other`.
    pub fn difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len());
        self.merge_walk(other, |ordering| ordering == Ordering::Less, false, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Values present in exactly one of `self` and `other`.
    pub fn symmetric_difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
    where
        T: Clone,
    {
        let mut merged = Vec::with_capacity(self.len() + other.len());
        self.merge_walk(other, |ordering| ordering != Ordering::Equal, true, &mut merged);
        SortedSet::from_sorted_unique(merged, self.load_factor())
    }

    /// Walks both sorted sequences once, collecting the values that qualify.
    ///
    /// `keep` is asked about each value from `self` using how it compares to the
    /// current value from `other` (`Less` means "only in `self`", `Equal` means
    /// "in both"). `keep_other_only` decides whether values found solely in
    /// `other` are collected.
    fn merge_walk<F>(
        &self,
        other: &SortedSet<T>,
        keep: F,
        keep_other_only: bool,
        out: &mut Vec<T>,
    ) where
        T: Clone,
        F: Fn(Ordering) -> bool,
    {
        let mut left = self.iter().peekable();
        let mut right = other.iter().peekable();
        loop {
            match (left.peek(), right.peek()) {
                (Some(a), Some(b)) => match a.cmp(b) {
                    Ordering::Less => {
                        let a = left.next().expect("peeked");
                        if keep(Ordering::Less) {
                            out.push(a.clone());
                        }
                    }
                    Ordering::Greater => {
                        let b = right.next().expect("peeked");
                        if keep_other_only {
                            out.push(b.clone());
                        }
                    }
                    Ordering::Equal => {
                        let a = left.next().expect("peeked");
                        right.next();
                        if keep(Ordering::Equal) {
                            out.push(a.clone());
                        }
                    }
                },
                (Some(_), None) => {
                    let a = left.next().expect("peeked");
                    if keep(Ordering::Less) {
                        out.push(a.clone());
                    }
                }
                (None, Some(_)) => {
                    let b = right.next().expect("peeked");
                    if keep_other_only {
                        out.push(b.clone());
                    }
                }
                (None, None) => return,
            }
        }
    }

    /// Returns `true` when every value of `self` is also in `other`.
    pub fn is_subset_of(&self, other: &SortedSet<T>) -> bool {
        if self.len() > other.len() {
            return false;
        }
        let mut right = other.iter().peekable();
        for value in self.iter() {
            loop {
                match right.next() {
                    Some(candidate) => match candidate.cmp(value) {
                        Ordering::Less => continue,
                        Ordering::Equal => break,
                        Ordering::Greater => return false,
                    },
                    None => return false,
                }
            }
        }
        true
    }

    /// Returns `true` when every value of `other` is also in `self`.
    pub fn is_superset_of(&self, other: &SortedSet<T>) -> bool {
        other.is_subset_of(self)
    }

    /// Returns `true` when the two sets share no values.
    pub fn is_disjoint_from(&self, other: &SortedSet<T>) -> bool {
        let mut left = self.iter().peekable();
        let mut right = other.iter().peekable();
        while let (Some(a), Some(b)) = (left.peek(), right.peek()) {
            match a.cmp(b) {
                Ordering::Less => {
                    left.next();
                }
                Ordering::Greater => {
                    right.next();
                }
                Ordering::Equal => return false,
            }
        }
        true
    }
}

