        return false;
    }
    let mut right = other.iter();
    for value in self.iter() {
        loop {
            match right.next() {
                // Skip past values that `other` has and `self` does not.
                Some(candidate) if candidate < value => continue,
                Some(candidate) if candidate == value => break,
                // Either `other` moved past `value` or it ran out.
                _ => return false,
