//! A sorted map keyed by any `Ord` type, layered on [`SortedList`].
//!
//! Entries are stored as key/value pairs ordered by key alone, so the list's
//! binary searches double as key lookups.

use std::cmp::Ordering;
use std::fmt;

use crate::sorted_list::{SortedList, DEFAULT_LOAD_FACTOR};

/// A key/value pair ordered solely by its key.
struct Entry<K, V> {
    key: K,
    value: V,
}

impl<K: Ord, V> PartialEq for Entry<K, V> {
    fn eq(&self, other: &Self) -> bool {
        self.key == other.key
    }
}

impl<K: Ord, V> Eq for Entry<K, V> {}

impl<K: Ord, V> PartialOrd for Entry<K, V> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl<K: Ord, V> Ord for Entry<K, V> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.key.cmp(&other.key)
    }
}

impl<K: Clone, V: Clone> Clone for Entry<K, V> {
    fn clone(&self) -> Self {
        Entry {
            key: self.key.clone(),
            value: self.value.clone(),
        }
    }
}

/// A map whose keys are kept in ascending order.
pub struct SortedDict<K, V> {
    entries: SortedList<Entry<K, V>>,
}

impl<K, V> SortedDict<K, V> {
    /// Creates an empty map using [`DEFAULT_LOAD_FACTOR`].
    pub fn new() -> Self {
        Self::with_load_factor(DEFAULT_LOAD_FACTOR)
    }

    /// Creates an empty map with an explicit load factor.
    pub fn with_load_factor(load: usize) -> Self {
        SortedDict {
            entries: SortedList::with_load_factor(load),
        }
    }

    /// Number of entries in the map.
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Returns `true` when the map holds no entries.
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Removes every entry.
    pub fn clear(&mut self) {
        self.entries.clear();
    }

    /// Iterates over the entries in ascending key order.
    pub fn iter(&self) -> impl DoubleEndedIterator<Item = (&K, &V)> + '_ {
        self.entries.iter().map(|entry| (&entry.key, &entry.value))
    }

    /// Iterates over the keys in ascending order.
    pub fn keys(&self) -> impl DoubleEndedIterator<Item = &K> + '_ {
        self.entries.iter().map(|entry| &entry.key)
    }

    /// Iterates over the values, ordered by their keys.
    pub fn values(&self) -> impl DoubleEndedIterator<Item = &V> + '_ {
        self.entries.iter().map(|entry| &entry.value)
    }

    /// Returns the entry at rank `idx` in key order.
    pub fn get_index(&self, idx: usize) -> Option<(&K, &V)> {
        self.entries
            .get(idx)
            .map(|entry| (&entry.key, &entry.value))
    }

    /// Returns the entry with the smallest key.
    pub fn first_key_value(&self) -> Option<(&K, &V)> {
