    }
}

impl<K: Clone, V: Clone> Clone for SortedDict<K, V> {
    fn clone(&self) -> Self {
        SortedDict {
            entries: self.entries.clone(),
        }
    }
}

impl<K: fmt::Debug, V: fmt::Debug> fmt::Debug for SortedDict<K, V> {
