}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn insert_get_and_replace() {
        let mut dict: SortedDict<i32, &str> = SortedDict::with_load_factor(2);
        assert_eq!(dict.insert(3, "three"), None);
        assert_eq!(dict.insert(1, "one"), None);
        assert_eq!(dict.insert(2, "two"), None);
        assert_eq!(dict.insert(1, "uno"), Some("one"));
        assert_eq!(dict.len(), 3);
        assert_eq!(dict.get(&1), Some(&"uno"));
        assert_eq!(dict.get(&2), Some(&"two"));
        assert_eq!(dict.get(&9), None);
        assert!(dict.contains_key(&3));
        assert!(!dict.contains_key(&4));

        *dict.get_mut(&2).unwrap() = "TWO";
        assert_eq!(dict.get(&2), Some(&"TWO"));
        assert!(dict.get_mut(&99).is_none());
    }

    #[test]
    fn keys_stay_ordered_across_splits() {
        let mut dict: SortedDict<i32, i32> = SortedDict::with_load_factor(2);
        for key in (0..60).rev() {
            dict.insert(key, key * 10);
        }
        assert_eq!(dict.len(), 60);
        assert_eq!(dict.keys().copied().collect::<Vec<i32>>(), (0..60).collect::<Vec<i32>>());
        assert_eq!(dict.values().copied().collect::<Vec<i32>>(), (0..60).map(|k| k * 10).collect::<Vec<i32>>());
        for key in 0..60 {
            assert_eq!(dict.get(&key), Some(&(key * 10)), "get({key})");
            assert_eq!(dict.get_index(key as usize), Some((&key, &(key * 10))));
        }
        assert_eq!(dict.get_index(60), None);
    }

