    fn removal_and_ends() {
        let mut dict: SortedDict<i32, i32> = SortedDict::with_load_factor(2);
        for key in 0..40 {
            dict.insert(key, key);
        }
        assert_eq!(dict.remove(&0), Some(0));
        assert_eq!(dict.remove(&0), None);
        assert_eq!(dict.remove(&39), Some(39));
        assert_eq!(dict.remove(&20), Some(20));
        assert_eq!(dict.len(), 37);
        assert_eq!(dict.first_key_value(), Some((&1, &1)));
        assert_eq!(dict.last_key_value(), Some((&38, &38)));
        assert_eq!(dict.pop_first(), Some((1, 1)));
        assert_eq!(dict.pop_last(), Some((38, 38)));
