        assert_eq!(dict.bisect_left(&20), 1);
        assert_eq!(dict.bisect_right(&20), 2);
        assert_eq!(dict.bisect_left(&25), 2);
        assert_eq!(dict.bisect_right(&99), 3);
        assert_eq!(dict.bisect_left(&0), 0);
