    #[test]
    fn traits_and_conversions() {
        let mut dict: SortedDict<i32, i32> = SortedDict::default();
        dict.extend([(2, 20), (1, 10)]);
        assert_eq!(format!("{:?}", dict), "{1: 10, 2: 20}");
