//! Faithful Rust versions of the C `<stdlib.h>` string-to-integer routines.
//!
//! The original program parsed its argument with `std::atoi`, which never
//! reports failure: it skips leading whitespace, accepts one optional sign,
//! consumes as many digits as it can, and yields `0` when there are none.
//! `Rust`'s `str::parse` rejects all of those inputs instead, so the C
//! behaviour is reproduced here rather than approximated.

/// Matches the C `isspace` classification for the default locale.
fn is_c_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Equivalent of `strtol(s, NULL, 10)`.
///
/// Values that do not fit saturate at [`i64::MIN`] / [`i64::MAX`], exactly as
/// `strtol` clamps to `LONG_MIN` / `LONG_MAX` when it sets `ERANGE`.
pub fn c_strtol(s: &str) -> i64 {
    let bytes = s.as_bytes();
    let mut at = 0usize;

    while at < bytes.len() && is_c_space(bytes[at]) {
        at += 1;
    }

    let mut negative = false;
    if at < bytes.len() && (bytes[at] == b'+' || bytes[at] == b'-') {
        negative = bytes[at] == b'-';
        at += 1;
    }

    let mut magnitude: i64 = 0;
    let mut saturated = false;
    while at < bytes.len() && bytes[at].is_ascii_digit() {
        let digit = i64::from(bytes[at] - b'0');
        if !saturated {
            match magnitude.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(next) => magnitude = next,
                // Keep scanning digits, as `strtol` does, but stop accumulating.
                None => saturated = true,
            }
        }
        at += 1;
    }

    if saturated {
        // `-9223372036854775808` overflows the positive magnitude yet is a
        // representable result; `i64::MIN` is both the clamp and the answer.
        return if negative { i64::MIN } else { i64::MAX };
    }
    if negative {
        -magnitude
    } else {
        magnitude
    }
}

/// Equivalent of `atoi(s)`: `strtol` truncated to `int` width.
///
/// glibc implements `atoi` as `(int) strtol(...)`, so out-of-range input wraps
/// modulo 2^32 rather than clamping. `atoi("2147483648")` is `-2147483648`.
pub fn c_atoi(s: &str) -> i32 {
    c_strtol(s) as i32
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_decimal_numbers() {
        assert_eq!(c_atoi("0"), 0);
        assert_eq!(c_atoi("6"), 6);
        assert_eq!(c_atoi("42"), 42);
        assert_eq!(c_atoi("000123"), 123);
        assert_eq!(c_atoi("-7"), -7);
        assert_eq!(c_atoi("+5"), 5);
        assert_eq!(c_atoi("-0"), 0);
    }

    #[test]
    fn leading_whitespace_is_skipped() {
        assert_eq!(c_atoi("   7"), 7);
        assert_eq!(c_atoi("\t\n\r\x0b\x0c8"), 8);
        assert_eq!(c_atoi("  7  "), 7);
        assert_eq!(c_atoi("  -7"), -7);
        // Whitespace after the sign terminates the number.
        assert_eq!(c_atoi("- 7"), 0);
        assert_eq!(c_atoi("+ 7"), 0);
    }

    #[test]
    fn parsing_stops_at_the_first_non_digit() {
        assert_eq!(c_atoi("12abc"), 12);
        assert_eq!(c_atoi("3.9"), 3);
        assert_eq!(c_atoi("1e3"), 1);
        assert_eq!(c_atoi("0x10"), 0);
        assert_eq!(c_atoi("010"), 10);
        assert_eq!(c_atoi("5-3"), 5);
        assert_eq!(c_atoi("2 99"), 2);
    }

    #[test]
    fn absent_digits_yield_zero() {
        assert_eq!(c_atoi(""), 0);
        assert_eq!(c_atoi("abc"), 0);
        assert_eq!(c_atoi("   "), 0);
        assert_eq!(c_atoi("-"), 0);
        assert_eq!(c_atoi("+"), 0);
        assert_eq!(c_atoi("--5"), 0);
        assert_eq!(c_atoi("+-5"), 0);
        assert_eq!(c_atoi("\u{fffd}5"), 0);
    }

    #[test]
    fn out_of_range_input_wraps_like_a_c_int_cast() {
        assert_eq!(c_atoi("2147483647"), i32::MAX);
        assert_eq!(c_atoi("-2147483648"), i32::MIN);
        assert_eq!(c_atoi("2147483648"), i32::MIN);
        assert_eq!(c_atoi("4294967296"), 0);
        assert_eq!(c_atoi("-2147483649"), i32::MAX);
        // Beyond `long`: `strtol` clamps, then the cast truncates.
        assert_eq!(c_strtol("9223372036854775807"), i64::MAX);
        assert_eq!(c_strtol("9223372036854775808"), i64::MAX);
        assert_eq!(c_strtol("99999999999999999999999"), i64::MAX);
        assert_eq!(c_strtol("-9223372036854775808"), i64::MIN);
        assert_eq!(c_strtol("-9223372036854775809"), i64::MIN);
        assert_eq!(c_strtol("-99999999999999999999999"), i64::MIN);
        assert_eq!(c_atoi("9223372036854775807"), -1);
        assert_eq!(c_atoi("99999999999999999999999"), -1);
        assert_eq!(c_atoi("-9223372036854775808"), 0);
        assert_eq!(c_atoi("-99999999999999999999999"), 0);
        // 0x174876E7FF truncated to 32 bits.
        assert_eq!(c_atoi("99999999999"), 1215752191);
    }
}

